registry_model = env['x_hr.recruitment_document'].sudo()
sign_template_model = env['sign.template'].sudo()
sign_document_model = env['sign.document'].sudo()
sign_item_model = env['sign.item'].sudo()
sign_role_model = env['sign.item.role'].sudo()
sign_send_model = env['sign.send.request'].sudo()
sign_send_signer_model = env['sign.send.request.signer'].sudo()
sign_request_model = env['sign.request'].sudo()
partner_model = env['res.partner'].sudo()

signature_type = env.ref('sign.sign_item_type_signature', raise_if_not_found=False)

applicant_role = (
    sign_role_model.search([('name', '=', 'Applicant')], order='id asc', limit=1)
    or sign_role_model.search([('name', '=', 'Employee')], order='id asc', limit=1)
    or sign_role_model.search([('name', '=', 'Customer')], order='id asc', limit=1)
    or sign_role_model.search([('name', '=', 'Signatory')], order='id asc', limit=1)
    or sign_role_model.search([], order='id asc', limit=1)
)

setup_error = False
if not signature_type:
    setup_error = 'Odoo Sign signature field type could not be found: sign.sign_item_type_signature.'
elif not applicant_role:
    setup_error = 'No Odoo Sign signer role was found. Create an Applicant, Employee, Customer, or Signatory role before sending F-0004.'

action = False

for rec in records.sudo():
    if setup_error:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'إعداد توقيع أودو غير مكتمل',
                'message': setup_error,
                'type': 'warning',
                'sticky': True,
            }
        }
        continue

    if rec.x_declaration_type != 'legal_documents_validity_declaration':
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'نوع إقرار غير مدعوم',
                'message': 'الإرسال عبر توقيع أودو متاح حالياً فقط لإقرار F-0004.',
                'type': 'warning',
                'sticky': False,
            }
        }
        continue

    if rec.x_state == 'signed':
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'F-0004 موقّع مسبقاً',
                'message': 'هذا الإقرار موقّع مسبقاً. لن يتم إنشاء طلب توقيع مكرر.',
                'type': 'warning',
                'sticky': False,
            }
        }
        continue

    if rec.x_state != 'generated' or not rec.x_pdf_attachment_id:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'F-0004 غير جاهز للإرسال',
                'message': 'أنشئ ملف F-0004 PDF قبل إرساله عبر توقيع أودو.',
                'type': 'warning',
                'sticky': False,
            }
        }
        continue

    applicant = rec.x_applicant_id
    if not applicant:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'لا يوجد متقدم',
                'message': 'لا يمكن إرسال F-0004 بدون متقدم مرتبط.',
                'type': 'warning',
                'sticky': True,
            }
        }
        continue

    applicant_name = applicant.partner_name or applicant.name or applicant.display_name
    applicant_email = applicant.email_from or False

    applicant_partner = False
    if 'partner_id' in applicant._fields and applicant.partner_id:
        applicant_partner = applicant.partner_id.sudo()

    if not applicant_partner and applicant_email:
        applicant_partner = partner_model.search([('email', '=', applicant_email)], order='id asc', limit=1)

    if not applicant_partner and applicant_email:
        applicant_partner = partner_model.create({
            'name': applicant_name or applicant_email,
            'email': applicant_email,
        })

    if not applicant_partner or not (applicant_partner.email or applicant_email):
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'بريد المتقدم غير موجود',
                'message': 'أضف بريداً إلكترونياً للمتقدم قبل إرسال F-0004 عبر توقيع أودو.',
                'type': 'warning',
                'sticky': False,
            }
        }
        continue

    pdf_attachment = rec.x_pdf_attachment_id
    filename = pdf_attachment.name or ('%s - F-0004 Legal Documents Validity Declaration.pdf' % applicant_name)

    registry_doc = registry_model.search([
        ('x_document_type', '=', 'legal_documents_validity_declaration'),
        ('x_source_model', '=', 'x_hr.applicant_declaration'),
        ('x_source_res_id', '=', rec.id),
    ], order='id desc', limit=1)

    if not registry_doc:
        latest_any = registry_model.search([
            ('x_document_type', '=', 'legal_documents_validity_declaration'),
            ('x_applicant_id', '=', applicant.id),
        ], order='x_version desc, id desc', limit=1)

        next_version = (latest_any.x_version or 0) + 1 if latest_any else 1

        registry_doc = registry_model.create({
            'x_name': 'إقرار صحة المستندات - %s - v%s' % (applicant_name, next_version),
            'x_applicant_id': applicant.id,
            'x_document_type': 'legal_documents_validity_declaration',
            'x_state': 'generated',
            'x_generated_attachment_id': pdf_attachment.id,
            'x_version': next_version,
            'x_generated_on': rec.x_generated_on or datetime.datetime.now(),
            'x_responsible_user_id': env.user.id,
            'x_source_model': 'x_hr.applicant_declaration',
            'x_source_res_id': rec.id,
            'x_notes': 'تم استرداد سجل F-0004 في سجل مستندات التوظيف أثناء الإرسال عبر توقيع أودو.',
        })

    if registry_doc.x_state == 'signed':
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'F-0004 موقّع مسبقاً',
                'message': 'سجل مستندات التوظيف لهذا الإقرار موقّع مسبقاً.',
                'type': 'warning',
                'sticky': False,
            }
        }
        continue

    if registry_doc.x_sign_request_res_id:
        existing_request = sign_request_model.browse(registry_doc.x_sign_request_res_id)
        if existing_request.exists():
            existing_state = existing_request.state or registry_doc.x_sign_request_state or 'unknown'
            if existing_state not in ['cancelled', 'canceled']:
                if existing_state in ['signed', 'completed']:
                    message = 'طلب توقيع أودو المرتبط موقّع بالفعل. استخدم مزامنة نتيجة التوقيع لإغلاق السجل.'
                else:
                    message = 'يوجد طلب توقيع أودو نشط لهذا الإقرار بحالة "%s". لن يتم إنشاء طلب مكرر.' % existing_state

                action = {
                    'type': 'ir.actions.client',
                    'tag': 'display_notification',
                    'params': {
                        'title': 'تم منع طلب توقيع مكرر',
                        'message': message,
                        'type': 'warning',
                        'sticky': True,
                    }
                }
                continue

    sent_on = datetime.datetime.now()
    validity_date = datetime.date.today() + datetime.timedelta(days=60)

    sign_template = sign_template_model.create({
        'name': filename,
        'user_id': env.user.id,
        'signature_request_validity': 60,
    })

    sign_document = sign_document_model.create({
        'template_id': sign_template.id,
        'attachment_id': pdf_attachment.id,
        'name': filename,
        'sequence': 1,
    })

    # F-0004 applicant-only Sign profile.
    # Coordinates measured from the generated one-page F-0004 PDF:
    # applicant signature blank cell, page 1, left/main signature area.
    sign_item_model.create({
        'document_id': sign_document.id,
        'type_id': signature_type.id,
        'responsible_id': applicant_role.id,
        'page': 1,
        'posX': 0.210,
        'posY': 0.570,
        'width': 0.360,
        'height': 0.056,
        'required': True,
        'name': 'Signature',
        'alignment': 'left',
        'constant': False,
    })

    subject = 'Signature Request - %s' % filename
    body = '<p>Please review and sign the attached F-0004 Legal Documents Validity Declaration.</p>'

    send_vals = {
        'template_id': sign_template.id,
        'signer_id': applicant_partner.id,
        'subject': subject,
        'body': body,
        'validity': validity_date,
        'certificate_reference': False,
        'reminder_enabled': False,
        'model': 'x_hr.applicant_declaration',
        'res_ids': str([rec.id]),
    }

    if 'reference_doc' in sign_send_model._fields:
        send_vals['reference_doc'] = 'hr.applicant,%s' % applicant.id

    send_request = sign_send_model.create(send_vals)

    if send_request.signer_ids:
        signer_line = send_request.signer_ids.filtered(lambda line: line.role_id.id == applicant_role.id)[:1]
        if not signer_line:
            signer_line = send_request.signer_ids[:1]
        signer_line.sudo().write({
            'partner_id': applicant_partner.id,
            'mail_sent_order': 1,
        })
    else:
        sign_send_signer_model.create({
            'sign_send_request_id': send_request.id,
            'role_id': applicant_role.id,
            'partner_id': applicant_partner.id,
            'mail_sent_order': 1,
        })

    send_request.send_request()

    generated_request = sign_request_model.search([
        ('template_id', '=', sign_template.id),
        ('request_item_ids.partner_id', '=', applicant_partner.id),
    ], order='create_date desc, id desc', limit=1)

    if generated_request:
        if 'reference_doc' in sign_request_model._fields:
            generated_request.sudo().write({'reference_doc': 'hr.applicant,%s' % applicant.id})

        registry_doc.write({
            'x_state': 'signature_requested',
            'x_sent_on': sent_on,
            'x_responsible_user_id': env.user.id,
            'x_source_model': 'x_hr.applicant_declaration',
            'x_source_res_id': rec.id,
            'x_signature_mode': 'native_sign',
            'x_sign_request_model': 'sign.request',
            'x_sign_request_res_id': generated_request.id,
            'x_sign_request_reference': generated_request.reference or filename,
            'x_sign_request_state': generated_request.state or 'sent',
            'x_sign_request_url': '/odoo/sign/%s' % generated_request.id,
            'x_generated_attachment_id': pdf_attachment.id,
            'x_notes': ((registry_doc.x_notes or '') + '\\nNative Odoo Sign request created for F-0004 on %s. Request ID: %s. Applicant: %s.' % (sent_on, generated_request.id, applicant_partner.display_name)).strip(),
        })

        rec.write({
            'x_state': 'signature_requested',
            'x_sent_on': sent_on,
        })

        rec.message_post(body='تم إرسال F-0004 عبر توقيع أودو إلى %s.' % applicant_partner.display_name)
        applicant.message_post(body='تم إرسال إقرار F-0004 عبر توقيع أودو إلى %s.' % applicant_partner.display_name)

        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'تم إرسال F-0004 للتوقيع',
                'message': 'تم إنشاء طلب توقيع أودو وإرساله إلى %s.' % applicant_partner.display_name,
                'type': 'success',
                'sticky': False,
                'next': {'type': 'ir.actions.client', 'tag': 'reload'},
            }
        }
    else:
        registry_doc.write({
            'x_state': 'generated',
            'x_signature_mode': 'native_sign',
            'x_sign_request_model': 'sign.request',
            'x_sign_request_reference': filename,
            'x_sign_request_state': 'lookup_failed_after_send_request',
            'x_notes': ((registry_doc.x_notes or '') + '\\nNative Odoo Sign send_request() executed for F-0004 on %s, but the generated sign.request could not be located automatically. Dynamic template ID: %s.' % (sent_on, sign_template.id)).strip(),
        })

        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'تعذر العثور على طلب التوقيع',
                'message': 'تم تنفيذ الإرسال، لكن لم يتم العثور على sign.request تلقائياً. راجع تطبيق التوقيع قبل إعادة المحاولة.',
                'type': 'warning',
                'sticky': True,
            }
        }

    break

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}

target_declaration_type = 'policies_compliance_declaration'
target_document_type = 'policies_compliance_declaration'
target_code = 'F-0007'

registry_model = env['x_hr.recruitment_document'].sudo()
sign_request_model = env['sign.request'].sudo()
attachment_model = env['ir.attachment'].sudo()
action = False


def toast(title, message, kind='warning', sticky=False, reload=False):
    params = {
        'title': title,
        'message': message,
        'type': kind,
        'sticky': sticky,
    }
    if reload:
        params['next'] = {'type': 'ir.actions.client', 'tag': 'reload'}
    return {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': params,
    }


def looks_like_certificate(attachment):
    name = (attachment.name or '').lower()
    return (
        'certificate' in name
        or 'completion' in name
        or 'completed' in name
        or 'history' in name
        or 'audit' in name
        or 'trail' in name
        or 'شهادة' in name
        or 'إكمال' in name
        or 'اكمال' in name
    )


for rec in records.sudo():
    if rec.x_declaration_type != target_declaration_type:
        action = toast(
            'نوع إقرار غير مدعوم',
            'هذه المزامنة مخصصة فقط للنموذج %s.' % target_code,
            'warning',
            False,
        )
        continue

    applicant = rec.x_applicant_id
    if not applicant:
        action = toast('لا يوجد متقدم', 'لا يمكن مزامنة %s بدون متقدم مرتبط.' % target_code, 'warning', True)
        continue

    registry_doc = registry_model.search([
        ('x_document_type', '=', target_document_type),
        ('x_source_model', '=', 'x_hr.applicant_declaration'),
        ('x_source_res_id', '=', rec.id),
        ('x_signature_mode', '=', 'native_sign'),
        ('x_sign_request_res_id', '!=', False),
    ], order='x_version desc, id desc', limit=1)

    if not registry_doc:
        registry_doc = registry_model.search([
            ('x_document_type', '=', target_document_type),
            ('x_applicant_id', '=', applicant.id),
            ('x_signature_mode', '=', 'native_sign'),
            ('x_sign_request_res_id', '!=', False),
        ], order='x_version desc, id desc', limit=1)

    if not registry_doc:
        action = toast(
            'لا يوجد طلب توقيع مرتبط',
            'لم يتم العثور على سجل %s مرتبط بطلب توقيع أودو.' % target_code,
            'warning',
            True,
        )
        continue

    sign_request = sign_request_model.browse(registry_doc.x_sign_request_res_id)
    if not sign_request.exists():
        registry_doc.write({'x_sign_request_state': 'missing_sign_request'})
        action = toast('طلب التوقيع غير موجود', 'طلب توقيع أودو المرتبط لم يعد موجوداً أو لا يمكن الوصول إليه.', 'warning', True)
        continue

    request_state = sign_request.state or 'unknown'

    registry_doc.write({
        'x_sign_request_state': request_state,
        'x_sign_request_reference': sign_request.reference or registry_doc.x_sign_request_reference,
    })

    if request_state not in ['signed', 'completed']:
        rec.message_post(body='طلب توقيع %s لم يكتمل بعد. حالة الطلب الحالية: %s.' % (target_code, request_state))
        applicant.message_post(body='تم فحص حالة توقيع %s. الحالة الحالية: %s.' % (target_code, request_state))
        action = toast('%s لم يكتمل توقيعه' % target_code, 'طلب توقيع أودو لا يزال بحالة: %s.' % request_state, 'warning', False)
        continue

    completed_attachments = sign_request.completed_document_attachment_ids

    related_attachments = attachment_model.search([
        ('res_model', '=', 'sign.request'),
        ('res_id', '=', sign_request.id),
        ('mimetype', '=', 'application/pdf'),
    ], order='create_date desc, id desc')

    applicant_attachments = attachment_model.search([
        ('res_model', '=', 'hr.applicant'),
        ('res_id', '=', applicant.id),
        ('mimetype', '=', 'application/pdf'),
    ], order='create_date desc, id desc')

    declaration_attachments = attachment_model.search([
        ('res_model', '=', 'x_hr.applicant_declaration'),
        ('res_id', '=', rec.id),
        ('mimetype', '=', 'application/pdf'),
