            'x_sign_request_state': 'signed_no_completed_attachment_found',
            'x_notes': ((registry_doc.x_notes or '') + '\\nOdoo Sign request %s is signed, but no completed document attachments were found during %s sync on %s.' % (sign_request.id, target_code, datetime.datetime.now())).strip(),
