            certificate_native = signed_copy
        signed_copy = False

    if signed_copy and rec.x_pdf_attachment_id and signed_copy.id == rec.x_pdf_attachment_id.id:
        signed_copy = False

    certificate_copy = registry_doc.x_sign_certificate_attachment_id

    if not certificate_copy and certificate_native:
        certificate_name = certificate_native.name or ('Certificate of completion - %s - %s.pdf' % (target_code, applicant.partner_name or applicant.name or applicant.display_name))
