    request_state = sign_request.state or 'unknown'

    registry_doc.write({
        'x_sign_request_state': request_state,
        'x_sign_request_reference': sign_request.reference or registry_doc.x_sign_request_reference,
    })

    if request_state not in ['signed', 'completed']:
        rec.message_post(body='طلب توقيع F-0004 لم يكتمل بعد. حالة الطلب الحالية: %s.' % request_state)
        applicant.message_post(body='تم فحص حالة توقيع F-0004. الحالة الحالية: %s.' % request_state)

        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'F-0004 لم يكتمل توقيعه',
                'message': 'طلب توقيع أودو لا يزال بحالة: %s.' % request_state,
                'type': 'warning',
                'sticky': False,
            }
        }
        continue

    completed_attachments = sign_request.completed_document_attachment_ids

    # Robust attachment discovery:
    # Odoo Sign may expose the certificate and signed PDF differently depending on the
    # request/context. Never treat the certificate as the signed business document.
    related_attachments = env['ir.attachment'].sudo().search([
        ('res_model', '=', 'sign.request'),
        ('res_id', '=', sign_request.id),
        ('mimetype', '=', 'application/pdf'),
    ], order='create_date desc, id desc')

    all_completed_attachments = completed_attachments | related_attachments

