                'type': 'warning',
                'sticky': True,
            }
        }
        continue

    signed_copy = registry_doc.x_signed_attachment_id

    # Do not trust a previously linked signed attachment blindly.
    # Earlier F-0004 test syncs could place the certificate in the signed-document field.
    # If the current signed attachment looks like a certificate/history file, move it into
    # the certificate path and replace the signed document from the actual signed business PDF.
    if signed_copy:
        signed_copy_name = (signed_copy.name or '').lower()
        signed_copy_is_certificate = (
            'certificate' in signed_copy_name
            or 'completion' in signed_copy_name
            or 'history' in signed_copy_name
            or 'audit' in signed_copy_name
            or 'شهادة' in signed_copy_name
        )

        if signed_copy_is_certificate:
            if not certificate_native:
                certificate_native = signed_copy
            signed_copy = False

    certificate_copy = registry_doc.x_sign_certificate_attachment_id

    if not certificate_copy and certificate_native:
        certificate_copy_name = certificate_native.name or ('Certificate of completion - F-0004 - %s.pdf' % (applicant.partner_name or applicant.name or applicant.display_name))

        if certificate_native.res_model == 'hr.applicant' and certificate_native.res_id == applicant.id:
            certificate_copy = certificate_native
        else:
            certificate_copy = certificate_native.copy({
                'name': certificate_copy_name,
                'res_model': 'hr.applicant',
                'res_id': applicant.id,
            })

    if not signed_copy:
        signed_copy = signed_native.copy({
            'name': signed_native.name or ('Signed F-0004 - %s.pdf' % (applicant.partner_name or applicant.name or applicant.display_name)),
            'res_model': 'hr.applicant',
            'res_id': applicant.id,
        })

    signed_on = False
    signer_items = sign_request.request_item_ids.filtered(lambda item: item.state == 'completed')
    for signer_item in signer_items:
        if signer_item.write_date and (not signed_on or signer_item.write_date > signed_on):
            signed_on = signer_item.write_date

    if not signed_on and sign_request.write_date:
        signed_on = sign_request.write_date

    if not signed_on and sign_request.completion_date:
        signed_on = datetime.datetime.combine(sign_request.completion_date, datetime.time(12, 0, 0))

    if not signed_on:
        signed_on = datetime.datetime.now()

    registry_values = {
        'x_state': 'signed',
        'x_signed_attachment_id': signed_copy.id,
        'x_sign_completed_attachment_id': signed_copy.id,
        'x_sign_completed_on': signed_on,
        'x_signed_on': signed_on,
        'x_sign_request_state': request_state,
        'x_sign_request_reference': sign_request.reference or registry_doc.x_sign_request_reference,
        'x_responsible_user_id': env.user.id,
        'x_source_model': 'x_hr.applicant_declaration',
        'x_source_res_id': rec.id,
        'x_notes': ((registry_doc.x_notes or '') + '\\nNative Odoo Sign completion synced for F-0004 on %s. Sign request ID: %s. Signed artifact: %s.' % (datetime.datetime.now(), sign_request.id, signed_copy.name)).strip(),
    }

    if not registry_doc.x_sent_on:
        registry_values['x_sent_on'] = rec.x_sent_on or sign_request.create_date or signed_on

    if certificate_copy:
        registry_values['x_sign_certificate_attachment_id'] = certificate_copy.id

    registry_doc.write(registry_values)

    rec.write({
        'x_state': 'signed',
        'x_signed_on': signed_on,
        'x_signed_attachment_id': signed_copy.id,
    })

    rec.message_post(
        body='تمت مزامنة توقيع F-0004 وربط المستند الموقع: %s.' % signed_copy.name,
        attachment_ids=[signed_copy.id],
    )

    applicant_attachment_ids = [signed_copy.id]
    if certificate_copy:
        applicant_attachment_ids.append(certificate_copy.id)

    applicant.message_post(
        body='تم توقيع إقرار F-0004 عبر توقيع أودو وربط المستند الموقع والشهادة، عند توفرها، بسجل مستندات التوظيف.',
        attachment_ids=applicant_attachment_ids,
    )

    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': 'تم توقيع F-0004',
            'message': 'تمت مزامنة نتيجة التوقيع وربط المستند الموقع والشهادة عند توفرها.',
            'type': 'success',
            'sticky': False,
            'next': {'type': 'ir.actions.client', 'tag': 'reload'},
        }
    }

    break

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}

registry_model = env['x_hr.recruitment_document'].sudo()
action = False

for rec in records.sudo():
    registry_doc = registry_model.search([
        ('x_document_type', '=', 'legal_documents_validity_declaration'),
        ('x_source_model', '=', 'x_hr.applicant_declaration'),
        ('x_source_res_id', '=', rec.id),
        ('x_state', '=', 'signed'),
    ], order='id desc', limit=1)

    signed_attachment = rec.x_signed_attachment_id
    if registry_doc:
        signed_attachment = registry_doc.x_signed_attachment_id or registry_doc.x_sign_completed_attachment_id or signed_attachment

    if signed_attachment:
        signed_name = (signed_attachment.name or '').lower()
        looks_like_certificate = (
            'certificate' in signed_name
            or 'completion' in signed_name
            or 'history' in signed_name
            or 'audit' in signed_name
            or 'شهادة' in signed_name
        )

        if looks_like_certificate:
            action = {
                'type': 'ir.actions.client',
                'tag': 'display_notification',
                'params': {
                    'title': 'الملف الموقع غير صحيح',
                    'message': 'المرفق المرتبط كملف موقع يبدو أنه شهادة توقيع وليس نسخة F-0004 الموقعة. أعد تشغيل مزامنة نتيجة التوقيع لهذا الإقرار.',
                    'type': 'warning',
                    'sticky': True,
                }
            }
        else:
            action = {
                'type': 'ir.actions.act_url',
                'url': '/web/content/%s?download=true' % signed_attachment.id,
                'target': 'self',
            }
    else:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'لا يوجد ملف موقع',
                'message': 'لا يوجد ملف F-0004 موقع مرتبط بهذا الإقرار.',
                'type': 'warning',
                'sticky': False,
            }
        }
    break

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}

registry_model = env['x_hr.recruitment_document'].sudo()
sign_request_model = env['sign.request'].sudo()
attachment_model = env['ir.attachment'].sudo()
action = False


def toast(title, message, kind='warning', sticky=False):
    return {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': title,
            'message': message,
            'type': kind,
            'sticky': sticky,
        },
    }


def document_type_for(declaration):
    mapping = {
        'legal_documents_validity_declaration': 'legal_documents_validity_declaration',
        'policies_compliance_declaration': 'policies_compliance_declaration',
        'non_disclosure_agreement': 'non_disclosure_agreement',
    }
    return mapping.get(declaration.x_declaration_type) or declaration.x_declaration_type


def looks_like_certificate(attachment):
    name = (attachment.name or '').lower()
    return (
        'certificate' in name
        or 'completion' in name
        or 'completed' in name
        or 'history' in name
        or 'audit' in name
        or 'trail' in name
        or 'شهادة' in name
        or 'إكمال' in name
        or 'اكمال' in name
    )


def looks_like_business_document(attachment):
    name = (attachment.name or '').lower()
    return (
        'f-0004' in name
        or 'f-0007' in name
        or 'f-0009' in name
        or 'إقرار' in name
        or 'اقرار' in name
        or 'declaration' in name
        or 'agreement' in name
        or 'validity' in name
        or 'policies' in name
        or 'non-disclosure' in name
        or 'nda' in name
    )


def find_registry(declaration):
    applicant = declaration.x_applicant_id
    doc_type = document_type_for(declaration)

    registry = registry_model.search([
        ('x_document_type', '=', doc_type),
        ('x_source_model', '=', 'x_hr.applicant_declaration'),
        ('x_source_res_id', '=', declaration.id),
    ], order='x_version desc, id desc', limit=1)

    if registry:
        return registry

    if applicant:
        registry = registry_model.search([
            ('x_document_type', '=', doc_type),
            ('x_applicant_id', '=', applicant.id),
            ('x_signature_mode', '=', 'native_sign'),
            ('x_sign_request_res_id', '!=', False),
        ], order='x_version desc, id desc', limit=1)

    return registry


for rec in records.sudo():
    applicant = rec.x_applicant_id
    registry_doc = find_registry(rec)

    certificate = False
    candidate_attachments = attachment_model.browse([])

    if registry_doc and registry_doc.x_sign_certificate_attachment_id:
        certificate = registry_doc.x_sign_certificate_attachment_id

    sign_request = False
    if registry_doc and registry_doc.x_sign_request_res_id:
        sign_request = sign_request_model.browse(registry_doc.x_sign_request_res_id)
        if sign_request.exists():
            candidate_attachments |= sign_request.completed_document_attachment_ids
            candidate_attachments |= attachment_model.search([
                ('res_model', '=', 'sign.request'),
                ('res_id', '=', sign_request.id),
                ('mimetype', '=', 'application/pdf'),
            ], order='create_date desc, id desc')

    if applicant:
        candidate_attachments |= attachment_model.search([
            ('res_model', '=', 'hr.applicant'),
            ('res_id', '=', applicant.id),
            ('mimetype', '=', 'application/pdf'),
        ], order='create_date desc, id desc')

    candidate_attachments |= attachment_model.search([
        ('res_model', '=', 'x_hr.applicant_declaration'),
        ('res_id', '=', rec.id),
        ('mimetype', '=', 'application/pdf'),
    ], order='create_date desc, id desc')

    excluded_ids = []
    if rec.x_pdf_attachment_id:
        excluded_ids.append(rec.x_pdf_attachment_id.id)
    if rec.x_signed_attachment_id:
        excluded_ids.append(rec.x_signed_attachment_id.id)

    if registry_doc:
        if registry_doc.x_generated_attachment_id:
            excluded_ids.append(registry_doc.x_generated_attachment_id.id)
        if registry_doc.x_signed_attachment_id:
            excluded_ids.append(registry_doc.x_signed_attachment_id.id)
        if registry_doc.x_sign_completed_attachment_id:
            excluded_ids.append(registry_doc.x_sign_completed_attachment_id.id)

    if not certificate:
        for attachment in candidate_attachments:
            if attachment.id in excluded_ids:
                continue
            if looks_like_certificate(attachment):
                certificate = attachment
                break

    if not certificate:
        for attachment in candidate_attachments:
            if attachment.id in excluded_ids:
                continue
            if not looks_like_business_document(attachment):
                certificate = attachment
                break

    if certificate and applicant and not (certificate.res_model == 'hr.applicant' and certificate.res_id == applicant.id):
        certificate = certificate.copy({
            'name': certificate.name or ('Certificate of completion - %s.pdf' % (rec.x_declaration_code or rec.x_name or 'Declaration')),
            'res_model': 'hr.applicant',
            'res_id': applicant.id,
        })

    if certificate and registry_doc and (not registry_doc.x_sign_certificate_attachment_id or registry_doc.x_sign_certificate_attachment_id.id != certificate.id):
        registry_doc.write({
            'x_sign_certificate_attachment_id': certificate.id,
            'x_notes': ((registry_doc.x_notes or '') + '\\nSignature certificate backfilled by generic declaration certificate helper on %s. Certificate attachment: %s.' % (datetime.datetime.now(), certificate.name)).strip(),
        })

    if certificate:
        action = {
            'type': 'ir.actions.act_url',
            'url': '/web/content/%s?download=true' % certificate.id,
            'target': 'self',
        }
    else:
        doc_type = document_type_for(rec)
        debug_hint = 'document_type=%s' % doc_type
        if registry_doc:
            debug_hint += ', registry_id=%s, sign_request_id=%s, candidates=%s' % (
                registry_doc.id,
                registry_doc.x_sign_request_res_id or 'none',
                len(candidate_attachments),
            )
        action = toast(
            'لا توجد شهادة توقيع',
            'لم يتم العثور على شهادة توقيع في سجل المستندات أو طلب التوقيع أو مرفقات المتقدم. %s' % debug_hint,
            'warning',
            True,
        )
    break

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}
